package dominoes

// Domino is a pair of dots.
type Domino [2]int

// MakeChain returns a way to order the given dominoes so they form a
// closed chain: adjacent halves match, and the two unpaired halves
// (first and last) match each other. It returns ok=false if no such
// chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	chain := make([]Domino, len(input))
	used := make([]bool, len(input))

	var found bool

	// dfs extends the chain from the given end value, placing
	// remaining more dominoes.
	var dfs func(end int, remaining int)
	dfs = func(end int, remaining int) {
		if remaining == 0 {
			found = end == chain[0][0]
			return
		}
		for i, d := range input {
			if used[i] {
				continue
			}
			if d[0] == end {
				used[i] = true
				chain[len(chain)-remaining] = d
				dfs(d[1], remaining-1)
				if found {
					return
				}
				used[i] = false
			}
			if d[1] == end {
				used[i] = true
				chain[len(chain)-remaining] = Domino{d[1], d[0]}
				dfs(d[0], remaining-1)
				if found {
					return
				}
				used[i] = false
			}
		}
	}

	// Try every domino as the first stone of the chain.
	for s := 0; s < len(input); s++ {
		used[s] = true
		chain[0] = input[s]
		dfs(input[s][1], len(input)-1)
		if found {
			return chain, true
		}
		used[s] = false
	}

	return nil, false
}
